library(shiny)
library(bslib)
library(dplyr)
library(ggplot2)
library(DT)

world_url <- paste0(
  "https://raw.githubusercontent.com/guyabel/teaching-hku2026-rcourse/",
  "main/assignment-data/world.csv"
)

world <- read.csv("world.csv", check.names = FALSE)

world <- world |>
  mutate(
    year = as.integer(year),
    pop_m = pop / 1e6,
    region_sdg = as.character(region_sdg),
    region_geo = as.character(region_geo),
    region_geo_label = dplyr::recode(
      region_geo,
      "Latin America and the Caribbean" = "Latin America\nand the Caribbean"
    )
  )

regions <- sort(unique(world$region_sdg))
region_choices <- c("All SDG regions" = "all", setNames(regions, regions))
year_range <- range(world$year, na.rm = TRUE)
population_max <- max(world$pop_m, na.rm = TRUE)
population_breaks <- c(1, 10, 50, 100, 500, 1000)

ui <- page_sidebar(
  theme = bs_theme(
    version = 5,
    bootswatch = "flatly",
    primary = "#087f8c"
  ),
  title = tags$span(
    "The Demographic Transition Around the World",
    class = "app-title",
    style = "font-size: 2rem !important; font-weight: 700 !important;"
  ),
  head = tags$style(
    ".navbar-brand { font-size: 2rem !important; }"
  ),
  sidebar = sidebar(
    title = "Select Your Data",
    width = "25%",
    selectInput(
      inputId = "region",
      label = "SDG Region",
      choices = region_choices,
      selected = "all"
    ),
    sliderInput(
      inputId = "year",
      label = "Year",
      min = year_range[1],
      max = year_range[2],
      value = year_range[1],
      step = 1,
      sep = "",
      animate = animationOptions(interval = 500, loop = FALSE)
    ),
    helpText(
      "Each bubble is a country. Bubble area represents population."
    )
  ),
  navset_tab(
    nav_panel(
      title = "Explore the Relationship",
      layout_column_wrap(
        width = 1,
        card(
          plotOutput("demographic_plot", height = "650px")
        )
      )
    ),
    nav_panel(
      title = "View the Data",
      card(
        card_header("Country-Level Indicators"),
        card_body(
          p("Use the search box and column filters to inspect individual countries."),
          checkboxInput(
            inputId = "all_years",
            label = "Show All Years",
            value = FALSE
          ),
          downloadButton("download_data", "Download CSV"),
          DTOutput("demographic_table")
        )
      )
    )
  )
)

server <- function(input, output, session) {
  selected_region <- reactive({
    if (input$region == "all") {
      world
    } else {
      world |>
        filter(region_sdg == input$region)
    }
  })

  current_year_data <- reactive({
    selected_region() |>
      filter(
        year == input$year,
        !is.na(e0),
        !is.na(tfr),
        !is.na(pop)
      )
  })

  table_source <- reactive({
    data <- selected_region()

    if (!input$all_years) {
      data <- data |>
        filter(year == input$year)
    }

    data |>
      filter(!is.na(e0), !is.na(tfr), !is.na(pop))
  })

  plot_limits <- reactive({
    selected_region() |>
      summarise(
        e0_max = max(e0, na.rm = TRUE),
        tfr_max = max(tfr, na.rm = TRUE)
      )
  })

  table_data <- reactive({
    table_source() |>
      select(
        Country = name,
        ISO3 = iso3c,
        `SDG Region` = region_sdg,
        Year = year,
        Population = pop,
        `Life Expectancy` = e0,
        `Total Fertility Rate` = tfr
      )
  })

  output$demographic_plot <- renderPlot({
    ggplot(
      current_year_data(),
      aes(
        x = e0,
        y = tfr,
        size = pop_m,
        colour = region_geo_label
      )
    ) +
      geom_point(alpha = 0.75) +
      scale_size_continuous(
        name = "Population\n(millions)",
        range = c(2, 18),
        limits = c(0, population_max),
        breaks = population_breaks[population_breaks <= population_max]
      ) +
      labs(
        x = "Life Expectancy (Years)",
        y = "Total Fertility Rate (Children per Woman)",
        colour = "Geographic\nRegion"
      ) +
      annotate(
        geom = "text",
        x = Inf,
        y = Inf,
        label = input$year,
        hjust = 1.1,
        vjust = 1.2,
        size = 40,
        fontface = "bold",
        alpha = 0.12
      ) +
      scale_x_continuous(
        limits = c(0, plot_limits()$e0_max)
      ) +
      scale_y_continuous(
        limits = c(0, plot_limits()$tfr_max)
      ) +
      theme_minimal(base_size = 14) +
      theme(
        legend.position = "bottom",
        legend.box = "vertical",
        legend.box.just = "center",
        legend.direction = "horizontal",
        legend.justification = "center"
      ) +
      guides(
        colour = guide_legend(nrow = 1, byrow = TRUE),
        size = guide_legend(nrow = 1, byrow = TRUE)
      )
  })

  output$demographic_table <- renderDT({
    table_data() |>
      datatable(
        rownames = FALSE,
        options = list(pageLength = 10, scrollX = TRUE)
      ) |>
      formatRound(
        columns = c("Life Expectancy", "Total Fertility Rate"),
        digits = 2
      ) |>
      formatRound(columns = "Population", digits = 0, mark = ",")
  })

  output$download_data <- downloadHandler(
    filename = function() {
      if (input$all_years) {
        "demographic-data-all-years.csv"
      } else {
        paste0("demographic-data-", input$year, ".csv")
      }
    },
    content = function(file) {
      write.csv(table_data(), file, row.names = FALSE)
    }
  )
}

shinyApp(ui = ui, server = server)
